        p.won_at = (o.confirmed_at if o and o.confirmed_at else p.updated_at) or now
        p.won_by_id = o.confirmed_by_id if o else None
        p.won_note = "RC3 迁移：历史成交项目自动记录中标"
        p.sales_locked_at = now
        p.presale_phase = "成交"
        p.save(update_fields=["won_at", "won_by", "won_note", "sales_locked_at", "presale_phase"])


